mapper.select:
select version_status
from evaluation_rule_versions
where rule_version_id = #{ruleVersionId}

select area_id
from evaluation_areas
where rule_version_id = #{ruleVersionId}
  and area_code = #{areaCode}

select count(*)
from evaluation_items
where area_id = #{areaId}
  and item_code = #{parentItemCode}

select 
from evaluation_items ei
inner join evaluation_areas ea on ea.area_id = ei.area_id
inner join evaluation_rule_versions erv on erv.rule_version_id = ea.rule_version_id
where ei.area_id = #{areaId}
  and ei.item_code = #{itemCode}
